<div class="category-tree-row <?= (int)$this->selected===(int)$row['id']?'is-selected':'' ?>" data-tree-row><div class="tree-category-name"><button type="button" class="tree-drag-handle" data-drag-category="<?= (int)$row['id'] ?>" aria-label="جابه‌جایی <?= CHtml::encode($label) ?>" title="برای جابه‌جایی بکشید">⠿</button><button type="button" class="tree-toggle" data-toggle-branch aria-label="باز یا بسته کردن زیرمجموعه‌ها" aria-expanded="true">⌄</button><a href="<?= CHtml::encode(Yii::app()->createUrl($this->editRoute,array_merge(array('id'=>$row['id']),$menu?array('location'=>$this->location):array()))) ?>" data-pjax="1" data-pjax-target="#<?= CHtml::encode($this->editorId) ?>" data-pjax-reset-scroll="1" class="category-edit-link"><strong><?= CHtml::encode($label) ?></strong><small dir="ltr"><?= CHtml::encode($menu?$row['url']:$row['slug']) ?></small></a></div><span class="tree-category-thumbnail"><?php if($menu): ?><span class="tree-menu-state <?= $row['is_active']?'active':'' ?>"><?= $row['is_active']?'فعال':'خاموش' ?></span><?php elseif(!empty($row['image'])): ?><?= MediaService::responsive($row['image'],$label,array('loading'=>'lazy','sizes'=>'40px')) ?><?php endif; ?></span><span class="tree-product-count"><?= $menu?'':number_format($counts[$row['id']]??0) ?></span><div class="tree-row-actions"><button type="button" data-tree-step="before" aria-label="انتقال به بالا">↑</button><button type="button" data-tree-step="after" aria-label="انتقال به پایین">↓</button></div></div></div><?php endforeach; ?></div>
<?php if(!$rows): ?><p class="empty">هنوز آیتمی ساخته نشده است؛ از فرم کنار صفحه اضافه کنید.</p><?php endif; ?>
